-- Generated by playerHousing/tools/makeGuildServicesSql.py: the Guild Regeneration Pool's aura on EQEmu's auras (NPC-34), and the
-- keys the Teleportation Assistant and Zeflmin Werlikanin sell, each from the expansion its landing belongs to (NPC-43).
DELIMITER //
BEGIN NOT ATOMIC
  DECLARE assistantMerchant INT;
  DECLARE zeflminMerchant INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET assistantMerchant = (SELECT n.merchant_id FROM npc_types n JOIN real_estate_npc_items i ON i.npc_type_id = n.id WHERE i.item_id = 66640);
  SET zeflminMerchant = (SELECT merchant_id FROM npc_types WHERE id = 345004);
  IF EXISTS (SELECT 1 FROM real_estate_auras WHERE item_id = 66645) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'the guild regeneration pool already has an aura row';
  END IF;
  IF EXISTS (SELECT 1 FROM auras WHERE type = 31874) OR EXISTS (SELECT 1 FROM npc_types WHERE id = 2000100) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'the aura of the hall already has an auras or npc_types row';
  END IF;
  IF IFNULL(assistantMerchant, 0) = 0 OR IFNULL(zeflminMerchant, 0) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'the Teleportation Assistant or Zeflmin Werlikanin has no merchant list';
  END IF;
  IF EXISTS (SELECT 1 FROM merchantlist WHERE merchantid = assistantMerchant) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'the Teleportation Assistant already sells keys';
  END IF;
  IF (SELECT COUNT(*) FROM merchantlist WHERE merchantid = zeflminMerchant) <> 22
    OR EXISTS (SELECT 1 FROM merchantlist WHERE merchantid = zeflminMerchant AND item NOT IN (10092, 10094, 64191, 76000, 76001, 76002, 76003, 76004, 76005, 76006, 76007, 76009, 76010, 76011, 76012, 76070, 88735, 88736, 88737, 88738, 88739, 88740)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Zeflmin Werlikanin''s list is not ProjectEQ''s 22 keys';
  END IF;
  IF (SELECT COUNT(*) FROM items WHERE id IN (76005, 64191, 76010, 76006, 88737, 76000, 10094, 76002, 88735, 76003, 88736, 10092, 88742, 76001, 88739, 88740, 88741, 76011, 88743, 76012, 76004, 76009, 76070, 76007, 88738)) <> 25 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'a key the halls sell is not in items';
  END IF;
  IF (SELECT COUNT(DISTINCT zoneidnumber) FROM zone WHERE zoneidnumber IN (13, 27, 54, 71, 86, 100, 110, 117, 170, 186, 219, 283, 300, 362, 369, 397, 408, 414, 416, 442, 480, 700, 724, 752)) <> 24 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'a key lands in a zone with no zone row';
  END IF;
  START TRANSACTION;
  DELETE FROM merchantlist WHERE merchantid = zeflminMerchant;
  COMMIT;
END //
DELIMITER ;
